#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using MVZ2.IO;
using UnityEngine;

namespace MVZ2.Debugs
{
    public class MVZ2Logger : MonoBehaviour
    {
        public bool ExportLogFilePack(string destPath)
        {
            var dir = Application.persistentDataPath;
            if (!Directory.Exists(dir))
                return false;

            CloneCurrentLog();

            try
            {
                FileHelper.ValidateDirectoryExists(destPath);
                var sourceDirInfo = new DirectoryInfo(dir);
                var files = new string[]
                {
                    GetLogClonePath(),
                    GetPrevLogPath(),
                };
                using var stream = File.Open(destPath, FileMode.Create);
                using var archive = new ZipArchive(stream, ZipArchiveMode.Create);

                foreach (var filePath in files)
                {
                    if (!File.Exists(filePath))
                        continue;
                    var entryName = Path.GetRelativePath(dir, filePath);
                    entryName = entryName.Replace("\\", "/");
                    archive.CreateEntryFromFile(filePath, entryName);
                }
            }
            finally
            {
                DeleteLogClone();
            }
            return true;
        }

        #region 生命周期
        void OnEnable()
        {
            Application.logMessageReceivedThreaded += OnLogReceivedCallback;
        }
        void OnDisable()
        {
            Application.logMessageReceivedThreaded -= OnLogReceivedCallback;
        }
        private void Awake()
        {
            if (Instance && Instance != this)
            {
                Destroy(gameObject);
                return;
            }

            Instance = this;
            DontDestroyOnLoad(gameObject);

            InitLogWriter();
        }
        private void Update()
        {
            lock (logLock)
            {
                if (pendingLogs.Count == 0)
                    return;

                writeBuffer.Clear();

                writeBuffer.AddRange(pendingLogs);
                pendingLogs.Clear();
            }

            TryWriteLogs();
        }
#if UNITY_ANDROID || UNITY_IOS
        private void OnApplicationFocus(bool focus)
        {
            // 安卓失去焦点后，关闭文件流。
            // 因为安卓切换到其他应用时，可能会在后台被系统施放，而不调用OnApplicationQuit.
            if (!focus)
            {
                CloseLogWriter();
            }
            else
            {
                StartLogWriter();
            }
        }
#endif
        private void OnApplicationQuit()
        {
            // 退出游戏后，关闭文件流。
            CloseLogWriter();
        }
        #endregion

        #region 事件回调
        void OnLogReceivedCallback(string logString, string stackTrace, LogType type)
        {
            lock (logLock)
            {
                string timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
                pendingLogs.Add($"[{timestamp}][{type}]{logString}\n{stackTrace}\n\n");
            }
        }
        #endregion

        #region 输出日志内容
        private string GetLogPath()
        {
            return FileHelper.CombineFullPathSecure(Application.persistentDataPath, $"{fileName}{extension}");
        }
        private string GetPrevLogPath()
        {
            return FileHelper.CombineFullPathSecure(Application.persistentDataPath, $"{fileName}{prevSuffix}{extension}");
        }
        private string GetLogClonePath()
        {
            return FileHelper.CombineFullPathSecure(Application.persistentDataPath, $"{fileName}{cloneSuffix}{extension}");
        }
        #endregion

        #region LogWriter
        private void InitLogWriter()
        {
            try
            {
                string path = GetLogPath();
                // 开启游戏时将上一次的日志前缀加上-prev。
                if (File.Exists(path))
                {
                    string prevPath = GetPrevLogPath();
                    if (File.Exists(prevPath))
                    {
                        File.Delete(prevPath);
                    }
                    File.Move(path, prevPath);
                }
                StartLogWriter(path);
            }
            catch (Exception e)
            {
                Debug.LogError($"Failed to start in-game logger: {e}");
            }
        }
        private void StartLogWriter()
        {
            var path = GetLogPath();
            StartLogWriter(path);
        }
        private void StartLogWriter(string path)
        {
            lock (logExportLock)
            {
                if (logWriter == null)
                {
                    logWriter = new StreamWriter(path, true);
                }
            }
        }
        private void CloseLogWriter()
        {
            lock (logExportLock)
            {
                if (logWriter != null)
                {
                    logWriter.Dispose();
                    logWriter = null;
                }
            }
        }
        #endregion

        #region 导出日志
        private void CloneCurrentLog()
        {
            lock (logExportLock)
            {
                try
                {
                    CloseLogWriter();

                    DeleteLogClone();
                    var currentLogPath = GetLogPath();
                    if (File.Exists(currentLogPath))
                    {
                        var cloneLogPath = GetLogClonePath();
                        File.Copy(currentLogPath, cloneLogPath);
                    }
                    StartLogWriter(currentLogPath);
                }
                catch (Exception ex)
                {
                    Debug.LogError($"Failed to clone game log: {ex}");
                }
            }
        }
        private void DeleteLogClone()
        {
            try
            {
                var cloneLogPath = GetLogClonePath();
                if (!File.Exists(cloneLogPath))
                    return;
                File.Delete(cloneLogPath);
            }
            catch (Exception ex)
            {
                Debug.LogError($"Failed to delete game log clone: {ex}");
            }
        }
        #endregion
        private void TryWriteLogs()
        {
            string? errorToReport = null;
            bool reportAsWarning = false;

            lock (logExportLock)
            {
                // 1. 尝试初始化（限流重试）
                if (logWriter == null && Time.realtimeSinceStartup >= nextRetryRealtime)
                {
                    try
                    {
                        StartLogWriter();
                        logWriterInitFailed = false;
                    }
                    catch (Exception e)
                    {
                        // 只在第一次失败时打错误，后续降级为静默
                        if (!logWriterInitFailed)
                            errorToReport = $"Failed to start log writer, retry later: {e}";
                        logWriterInitFailed = true;
                        nextRetryRealtime = Time.realtimeSinceStartup + RetryIntervalSeconds;
                    }
                }

                // 2. 有 writer 就写
                if (writeBuffer.Count > 0)
                {
                    if (logWriter != null)
                    {
                        try
                        {
                            foreach (var log in writeBuffer)
                                logWriter.WriteLine(log);
                            logWriter.Flush();
                            writeBuffer.Clear();
                        }
                        catch (Exception e)
                        {
                            // 写入失败：丢弃 buffer，重置 writer，下次重新初始化
                            writeBuffer.Clear();
                            try { logWriter.Dispose(); } catch { }
                            logWriter = null;
                            nextRetryRealtime = Time.realtimeSinceStartup + RetryIntervalSeconds;
                            errorToReport = $"Failed to write logs: {e}";
                        }
                    }
                    else
                    {
                        // 3. writer 不可用，buffer 又不能无限涨：超出上限就丢弃最旧的
                        if (writeBuffer.Count > MaxBufferSize)
                        {
                            int drop = writeBuffer.Count - MaxBufferSize;
                            writeBuffer.RemoveRange(0, drop);
                            if (!logWriterInitFailed)
                                reportAsWarning = true;
                        }
                    }
                }
            }

            // 4. lock 外再输出，避免重入/死锁
            if (errorToReport != null)
            {
                if (reportAsWarning)
                    Debug.LogWarning(errorToReport);
                else
                    Debug.LogError(errorToReport);
            }
        }

        public static MVZ2Logger Instance { get; private set; } = null!;
        [SerializeField]
        string fileName = "mvz2_log";
        [SerializeField]
        string cloneSuffix = "-current";
        [SerializeField]
        string prevSuffix = "-prev";
        [SerializeField]
        string extension = ".log";
        StreamWriter? logWriter;
        private readonly List<string> pendingLogs = new();
        private readonly List<string> writeBuffer = new();
        private bool logWriterInitFailed = false;
        private float nextRetryRealtime = 0;
        private const float RetryIntervalSeconds = 10f; // 10s 后重试
        private const int MaxBufferSize = 10_000;   // 缓冲上限，防止 OOM

        readonly object logLock = new object();
        readonly object logExportLock = new object();
    }
}
